package com.codeguardian.service.auth; import cn.dev33.satoken.stp.StpInterface; import com.codeguardian.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component; import java.util.*; @Component @RequiredArgsConstructor public class SaPermissionImpl implements StpInterface{private final UserRoleRepository users;private final RolePermissionRepository roles;public List<String> getPermissionList(Object id,String type){Set<String> out=new HashSet<>();for(var r:users.findByUserId(Long.parseLong(String.valueOf(id))))out.addAll(roles.findPermissionCodesByRoleId(r.getRoleId()));return new ArrayList<>(out);}public List<String> getRoleList(Object id,String type){return users.findRoleCodesByUserId(Long.parseLong(String.valueOf(id)));}}
